// Discovery order: show the expressive controls before the exhaustive reference.
// Each specimen appears once, so search and collection exports share this order.
const LEADING_FAMILIES = ['Colour tools', 'Design workspace', 'Primitives'];
const COLOUR_ORDER = ['wheel', 'palettePreview', 'colorTriggers', 'colorField', 'colorFine', 'swatchCard', 'colorAdvanced', 'seal'];
export const COMPONENT_SECTIONS: Section[] = [
  ...LEADING_FAMILIES.flatMap(title => AUDIT_SECTIONS.filter(section => section.title === title)),
  ...AUDIT_SECTIONS.filter(section => !LEADING_FAMILIES.includes(section.title)),
].map(section => section.title === 'Colour tools' ? {
  ...section,
  blurb: 'Colour, with room to play. The same pickers, palette instruments and colour-space controls used in the studio and editor.',
  items: [...section.items].sort((a, b) => {
    const rank = (s: Specimen): number => { const i = COLOUR_ORDER.indexOf(s.live || ''); return i < 0 ? COLOUR_ORDER.length : i; };
    return rank(a) - rank(b);
  }),
} : section.title === 'Design workspace' ? { ...section, items: [section.items[0]!, section.items[3]!, section.items[1]!, section.items[2]!] } : section);
